width = 196
height = 196
dim = (width, height)
def createPixelArr(files, generate_synthetic=False):
    data = []
    for image in files:
        try:
            img_arr = cv2.imread(image, cv2.IMREAD_COLOR)
            # Check if image was successfully read
            if img_arr is not None:
                img_arr = cv2.cvtColor(img_arr, cv2.COLOR_BGR2RGB)
                resized_arr = cv2.resize(img_arr, (width, height))
                data.append(resized_arr)
            else:
                if generate_synthetic:
                    # Generate synthetic image data (random RGB values)
                    synthetic_img = np.random.randint(0, 256, (height, width, 3), dtype=np.uint8)
                    data.append(synthetic_img)
                else:
                    print(f"Warning: Could not read image {image}")
        except Exception as e:
            if generate_synthetic:
                # Generate synthetic image data on exception
                synthetic_img = np.random.randint(0, 256, (height, width, 3), dtype=np.uint8)
                data.append(synthetic_img)
            else:
                print(f"Error processing image {image}: {e}")
    return np.array(data)

class MyDataset(Dataset):
    def __init__(self, X, y):
        self.X = X
        self.y = y

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):
        # Convert from NHWC to NCHW format: (196, 196, 3) -> (3, 196, 196)
        x = self.X[idx].transpose(2, 0, 1)
        return x, self.y[idx]
